pes":null,"default_count":0},{"acl":"{postgres=X/postgres}","oid":"280168","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"5888883c32c339668b5690ae5006fe97","returns":"void","body_md5":"31385f42a8d635c7fab2b3b9a7cf5501","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session"],"signature":"mission_factory_owner.c464_runtime_admit_v1(uuid)","volatility":"v","input_types":"2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres}","oid":"280199","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"a33c378d6c70c559240e5b49a0cc834a","returns":"void","body_md5":"cff73ebdc2e2f8cb8e5c7d06079142a1","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session"],"signature":"mission_factory_owner.c474_bind_if_g2_v1(uuid)","volatility":"v","input_types":"2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres}","oid":"280201","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"439a245b591628191b5cceab46679ed5","returns":"jsonb","body_md5":"3560ee68d398db88993634b508e1fa9e","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session","p_round"],"signature":"mission_factory_owner.c474_terminal_preview_v1(uuid, uuid)","volatility":"v","input_types":"2950 2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres}","oid":"280249","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"c480c01144699ff0e1aaf7c83191d989","returns":"uuid","body_md5":"dea3374e630458570e47bcf738465580","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session","p_event","p_message","p_batch"],"signature":"mission_factory_owner.c485_parent_register_v1(uuid, uuid, uuid, uuid)","volatility":"v","input_types":"2950 29