ory_owner.c444_peaceful_boundary_v1(uuid, uuid)","volatility":"s","input_types":"2950 2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres}","oid":"309637","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"99a201e6ce212e220e0400dfe8f36581","returns":"uuid","body_md5":"b2f0b994bf444cdd91e1542e4197eb35","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session","p_encounter","p_request"],"signature":"mission_factory_owner.c444_peaceful_close_v1(uuid, uuid, uuid)","volatility":"v","input_types":"2950 2950 2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres}","oid":"309644","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"cd1bbef02893b4ccee1c8690a18204ae","returns":"boolean","body_md5":"c5bccecda692a98c7e21f29d15ea9b1d","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session","p_encounter"],"signature":"mission_factory_owner.c444_peaceful_history_complete_v1(uuid, uuid)","volatility":"s","input_types":"2950 2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}","oid":"31338","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"877b7860e80d4d9b8e5bae16cfea888f","returns":"jsonb","body_md5":"c742683c050a8fb6e23c01635d5b0ad0","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session","p_mode","p_reason","p_expected_control_version","p_request_key"],"signature":"public.master_v2_suspend(uuid, text, text, bigint, uuid)","volatility":"v","input_types":"2950 25 25 20 2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}","oid":"31339","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"6429cdee72bd7f6459adaaa9ad744efb","returns":"jsonb","body_md5":"f93081b87c166d9aca2b76b18ce85653","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session","p_expected_control_version","p_request_key"],"signature":"public.master_v2_resume(uuid, bigint, uuid)","volatility":"v","input_types":"2950 20 2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres,authenticated=X/postgres}","oid":"47914","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"e880037a61aba8aec7a2e2508fd9a0e7","returns":"jsonb","body_md5":"547fa5683d8c569d563adcb838d62c1f","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_master"],"signature":"public.universal_arena_state_v1(uuid)","volatility":"s","input_types":"2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres}","oid":"50131","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"1215fd1ea4ae983217d4f7a4630d6fe3","returns":"jsonb","body_md5":"1fad310e5f479e8561fdb390be270f2b","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_master"],"signature":"mission_generic_owner.arena_state(uuid)","volatility":"v","input_types":"2950","returns_set":false,"all_arg_types":null,"default_count":0},{"acl":"{postgres=X/postgres}","oid":"50701","owner":"postgres","config":["search_path=\"\""],"secdef":true,"strict":false,"ddl_md5":"4b6b00821dea7bf70e54d41d80634c6b","returns":"text","body_md5":"440de1076de422bb54ffddad64044ca3","defaults":null,"language":"plpgsql","parallel":"u","arg_modes":null,"arg_names":["p_session","p_encounter"],"signature":"mission_creation_owner.combat_outcome(uuid, uuid)","volatility":"s","input_types":"2950 2950","returns_set":false,"all_arg_types":null,"default_count":0}]$pins$::jsonb) LOOP SELECT jsonb_build_object('signature',format('%I.%I',n.nspname,p.proname)||'('||oidvectortypes(p.proargtypes)||')','oid',p.oid::text,'owner',pg_get_userbyid(p.proowner),'config',p.proconfig,'acl',p.proacl::text,'secdef',p.prosecdef,'volatility',p.provolatile::text,'input_types',p.proargtypes::text,'all_arg_types',p.proallargtypes,'arg_modes',p.proargmodes,'arg_names',p.proargnames,'returns',p.prorettype::regtype::text,'returns_set',p.proretset,'language',(SELECT lanname FROM pg_language WHERE oid=p.prolang),'parallel',p.proparallel::text,'strict',p.proisstrict,'default_count',p.pronargdefaults,'defaults',pg_get_expr(p.proargdefaults,0),'body_md5',md5(p.prosrc),'ddl_md5',md5(pg_get_functiondef(p.oid))) INTO STRICT actual FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.oid=(pin->>'oid')::oid;IF actual IS DISTINCT FROM pin THEN RAISE EXCEPTION 'HUMAN34_FULL_ABI_DRIFT';END IF;END LOOP;
 IF ((WITH targets(label,character_id) AS (VALUES ('pg_tamako','f335b077-34a1-41c3-94aa-58ec674b649b'::uuid),('master_riuji','6bceee99-974f-426b-8d92-38b43b4a4267'::uuid)), resources AS (select t.label,c.rank,c.vita,c.vita_max,c.chakra,c.chakra_max,c.exp,c.xp_lifetime,c.money,c.pool_concesso,c.unspent_points,md5(jsonb_build_array(c.taijutsu,c.ninjutsu,c.genjutsu,c.forza,c.velocita,c.mente,c.resistenza,c.fuuinjutsu,c.kekkei_genkai,c.lealta,c.via,c.fama,c.slot_extra)::text) stats_md5,(select count(*) from public.character_inventory x where x.character_id=c.id) inventory_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.item_id,x.quantity,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_inventory x where x.character_id=c.id) inventory_md5,(select count(*) from public.lesson_progress x where x.user_id=c.user_id) lesson_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.lesson_id,x.completed_at) order by x.id),'[]'::jsonb)::text) from public.lesson_progress x where x.user_id=c.user_id) lesson_md5,(select count(*) from public.character_jutsu x where x.user_id=c.user_id) jutsu_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.jutsu_id,x.source,x.learned_at) order by x.id),'[]'::jsonb)::text) from public.character_jutsu x where x.user_id=c.user_id) jutsu_md5,(select count(*) from public.character_abilities x where x.character_id=c.id) ability_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.technique_id,x.state,x.sessions_done,x.started_at,x.activated_at) order by x.id),'[]'::jsonb)::text) from public.character_abilities x where x.character_id=c.id) ability_md5,(select count(*) from public.character_perks x where x.character_id=c.id) perk_count,(select md5(coalesce(jsonb_agg(jsonb_build_array(x.id,x.tipo,x.dettaglio,x.costo,x.grado_tecnica,x.created_at) order by x.id),'[]'::jsonb)::text) from public.character_perks x where x.character_id=c.id) perk_md5,(select count(*) from public.esame_prove x where x.candidate_user=c.user_id and x.stato='aperta') legacy_exam_open,(select count(*) from exam_regia_private.bindings x where x.owner_user=c.user_id and x.state<>'closed') legacy_binding_open,md5(jsonb_build_array(c.clan,c.element,c.element2,c.cercoterio,c.sigillo)::text) identity_build_md5 from targets t join public.characters c on c.id=t.character_id order by t.label) select jsonb_build_object('at',clock_timestamp(),'protected_md5',md5(jsonb_agg(to_jsonb(r) order by label)::text),'rows',count(*),'fields_per_pg',(select count(*) from jsonb_object_keys((select to_jsonb(x)-'label' from resources x limit 1)))) from resources r))->>'protected_md5' IS DISTINCT FROM 'd41adde267a202a8ff4c6c194eb0a09f' THEN RAISE EXCEPTION 'HUMAN34_REAL_RESOURCES_CHANGED';END IF;
END $guard$;
CREATE OR REPLACE FUNCTION public.mission_factory_quest_human_terminal_publish_v1(p_session uuid, p_event uuid, p_body text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q mission_factory_owner.quest_run_sources%rowtype;
  m public.master_v2_sessions%rowtype;
  r public.mission_run_state%rowtype;
  ev public.mission_run_events%rowtype;
  ob public.mission_run_outbox%rowtype;
  old mission_factory_owner.quest_terminal_receipts%rowtype;
  route jsonb; pub jsonb; opt_outcome text;
  receipt_id uuid:=gen_random_uuid(); publication uuid;
  public_facts jsonb; private_facts jsonb; receipt jsonb;
  public_sha text; private_sha text; has_next boolean;
  locked_location uuid;
begin
  PERFORM mission_factory_owner.c407_identity_v1(p_session);
  if auth.role() IS DISTINCT FROM 'authenticated' or p_session is null or p_event is null
     or p_request is null then
    raise exception 'MF_QUEST_TERMINAL_PUBLISH_INPUT' using errcode='42501'; end if;
  select location_id into strict locked_location
    from mission_factory_owner.quest_run_sources where session_id=p_session;
  perform 1 from public.locations where id=locked_location for update;
  perform public.master_v2_lock_scope(p_session);
  select * into strict m from public.master_v2_sessions where id=p_session for update;
  select * into strict q from mission_factory_owner.quest_run_sources
    where session_id=p_session for update;
  select * into strict r from public.mission_run_state
    where master_session_id=p_session for update;
  if q.location_id is distinct from locked_location
     or m.location_id is distinct from locked_location
  then raise exception 'MF_QUEST_TERMINAL_LOCATION_DRIFT' using errcode='40001'; end if;
  select * into strict ev from public.mission_run_events
    where id=p_event and master_session_id=p_session for share;
  select * into strict ob from public.mission_run_outbox
    where event_id=p_event and master_session_id=p_session for share;
  if ev.operation_kind<>'close' or ev.status<>'committed'
     or (ev.request_key_sha256 is distinct from mission_internal.request_key_sha256(p_request)
          and not exists(select 1 from mission_creation_owner.human_actions h
            join mission_factory_owner.quest_decision_receipts dr
              on dr.id=(ev.result->>'decision_receipt_id')::uuid
             and dr.session_id=p_session and dr.episode_id=q.episode_id
             and dr.source_sha256=q.source_sha256 and dr.plan_version_id=q.plan_version_id
             and dr.step_key=ev.step_after and dr.run_control_version=ev.version_before
            where h.master_session_id=p_session and h.actor_user=m.master_user
              and mission_internal.request_key_sha256(h.request_key)=ev.request_key_sha256
              and h.result=ev.result
              and ev.result->>'native_session_id'=p_session::text
              and ev.result->>'close_event_id'=p_event::text
              and ev.result->>'step_key'=ev.step_after
              and ev.result->>'run_version_before'=ev.version_before::text
              and ev.result->>'run_version_after'=ev.version_after::text))
     or ev.result->>'schema_version' is distinct from 'quest-native-close/1'
     or ev.result->>'quest_episode_id' is distinct from q.episode_id::text
     or ev.result->>'source_sha256' is distinct from q.source_sha256
     or ob.context_fingerprint is distinct from ev.context_fingerprint
  then raise exception 'MF_QUEST_TERMINAL_EVENT_DRIFT' using errcode='40001'; end if;
  pub:=mission_factory_owner.c412_manual_fato_write_v1(p_session,p_event,p_body,p_request);
  select * into strict ob from public.mission_run_outbox
    where event_id=p_event and master_session_id=p_session for share;
  publication:=(pub->>'publication_id')::uuid;
  if q.state='terminal' then
    select * into strict old from mission_factory_owner.quest_terminal_receipts
      where session_id=p_session and request_key=p_request for share;
    if old.close_event_id is distinct from p_event
       or old.publication_id is distinct from publication
       or old.id is distinct from q.terminal_receipt_id
    then raise exception 'MF_QUEST_TERMINAL_REPLAY_DRIFT' using errcode='40001'; end if;
    return old.receipt;
  end if;
  IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.c412_control WHERE singleton AND runtime_enabled AND terminal_enabled) THEN RAISE EXCEPTION 'C412_MANUAL_TERMINAL_DISABLED';END IF;
  if q.state<>'started' or m.stato<>'chiusura' or m.closed_at is not null
     or r.run_phase<>'in_corso' or r.control_version<>ev.version_after
     or r.last_event_id is distinct from p_event
     or ev.version_after is distinct from ev.version_before+1
     or ob.state is distinct from 'published'
     or ob.publication_id is distinct from publication
  then raise exception 'MF_QUEST_TERMINAL_PUBLISH_CAS' using errcode='40001'; end if;
  route:=mission_factory_owner.quest_terminal_route_v1(
    p_session,(ev.result->>'decision_receipt_id')::uuid,ev.version_before,ev.created_at);
  opt_outcome:=route->>'outcome';
  if opt_outcome is distinct from ev.result->>'outcome'
     or ev.result->>'step_key' is distinct from r.current_step_key
  then raise exception 'MF_QUEST_TERMINAL_OUTCOME_DRIFT' using errcode='42501'; end if;
  select exists(select 1 from mission_factory_owner.quest_episodes next_ep
    join mission_factory_owner.quest_episodes current_ep
      on current_ep.arc_id=next_ep.arc_id and next_ep.ordinal=current_ep.ordinal+1
    where current_ep.id=q.episode_id and exists(select 1 from mission_factory_owner.quest_arcs arc where arc.id=q.arc_id and arc.quest_kind='trama')) into has_next;
  public_facts:=jsonb_build_object('schema_version','quest-continuity-public/1',
    'quest_episode_id',q.episode_id,'outcome',opt_outcome,
    'terminal_publication_id',publication);
  private_facts:=jsonb_build_object('schema_version','quest-episode-continuity/1',
    'episode_ordinal',q.episode_ordinal,'terminal_receipt_id',receipt_id,
    'binding_sha256',(select snapshot_sha256 from mission_generic_owner.run_bindings where master_session_id=p_session),
    'previous_episode_terminal_receipt_id',q.previous_episode_terminal_receipt_id,
    'quest_arc_id',q.arc_id,'quest_episode_id',q.episode_id,
    'source_sha256',q.source_sha256,'plan_version_id',q.plan_version_id,
    'close_event_id',p_event,'decision_receipt_id',route->>'decision_receipt_id',
    'evidence_ref',route->>'evidence_ref','outcome',opt_outcome,
    'facts',(select coalesce(jsonb_agg(jsonb_build_object('receipt_id',dr.id,'step_key',dr.step_key,'run_control_version',dr.run_control_version,
       'facts',dr.facts,'route',dr.route) order by dr.issued_at,dr.id),'[]'::jsonb)
       from mission_factory_owner.quest_decision_receipts dr where dr.session_id=p_session),
    'npc_world_source_sha256',q.source_sha256,
    'terminal_publication_id',publication);
  public_sha:=mission_factory_owner.sha(public_facts);
  private_sha:=mission_factory_owner.sha(private_facts);
  receipt:=jsonb_build_object('schema_version','quest-episode-terminal/1',
    'request_key',p_request,'quest_arc_id',q.arc_id,
    'quest_episode_id',q.episode_id,'native_session_id',p_session,
    'source_sha256',q.source_sha256,'native_terminal_receipt_id',receipt_id,
    'outcome',opt_outcome,'continuity_public_sha256',public_sha,
    'continuity_private_sha256',private_sha,
    'next_episode_eligible',false,'reward_state','not_awarded_staff_simulation');
  insert into mission_factory_owner.quest_terminal_receipts(
    id,session_id,episode_id,request_key,close_event_id,publication_id,
    decision_receipt_id,source_sha256,outcome,continuity_public,
    continuity_private,continuity_public_sha256,continuity_private_sha256,receipt)
  values(receipt_id,p_session,q.episode_id,p_request,p_event,publication,
    (route->>'decision_receipt_id')::uuid,q.source_sha256,opt_outcome,
    public_facts,private_facts,public_sha,private_sha,receipt);
  update public.mission_run_state
    set run_phase=case when opt_outcome='success' then 'conclusa' else 'fallita' end,
      control_version=control_version+1,updated_at=clock_timestamp()
    where master_session_id=p_session and run_phase='in_corso'
      and control_version=ev.version_after and last_event_id=p_event;
  if not found then raise exception 'MF_QUEST_TERMINAL_RUN_FINAL_CAS' using errcode='40001'; end if;
  update public.master_v2_sessions
    set stato='chiusa',closed_at=clock_timestamp(),control_version=control_version+1
    where id=p_session and stato='chiusura' and closed_at is null;
  if not found then raise exception 'MF_QUEST_TERMINAL_MASTER_FINAL_CAS' using errcode='40001'; end if;
  update mission_factory_owner.quest_run_sources
    set state='terminal',control_version=control_version+1,
      terminal_receipt_id=receipt_id,terminal_at=clock_timestamp()
    where session_id=p_session and state='started' and terminal_receipt_id is null;
  if not found then raise exception 'MF_QUEST_TERMINAL_SOURCE_CAS' using errcode='40001'; end if;
  update mission_factory_owner.quest_episodes
    set state=case when opt_outcome='success' then 'completed' else 'failed' end,
      terminal_receipt=receipt
    where id=q.episode_id and arc_id=q.arc_id and state='in_progress'
      and terminal_receipt is null;
  if not found then raise exception 'MF_QUEST_TERMINAL_EPISODE_CAS' using errcode='40001'; end if;
  update mission_generic_owner.unified_source_windows sw set consumed_message_id=(pub->>'message_id')::uuid
    from mission_generic_owner.unified_batches ub, mission_factory_owner.quest_decision_receipts dr
    where dr.id=(route->>'decision_receipt_id')::uuid and dr.source_kind='narrative_event'
      and ub.id=dr.source_ref and sw.id=ub.source_window_id and sw.consumed_message_id is null;
  update mission_generic_owner.unified_batches ub set state='published',message_id=(pub->>'message_id')::uuid
    from mission_factory_owner.quest_decision_receipts dr where dr.id=(route->>'decision_receipt_id')::uuid
      and dr.source_kind='narrative_event' and ub.id=dr.source_ref and ub.state='preparing';
  update mission_factory_owner.quest_arcs
    set state=case when has_next then 'in_progress'
                   when opt_outcome='failure' then 'failed' else 'completed' end
    where id=q.arc_id and state='in_progress';
  if not found then raise exception 'MF_QUEST_TERMINAL_ARC_CAS' using errcode='40001'; end if;
  return receipt;
end; $function$;

